<template>
  <div class="login-page login-page--login">
    <div class="login-bg" aria-hidden="true" />
    <div v-if="bgSrc" class="bg-photo" aria-hidden="true">
      <img class="bg-photo__img" :src="bgSrc" alt="" />
      <div class="bg-photo__scrim" />
    </div>

    <div class="content content--login">
      <header class="header">
        <h1 class="title">Welcome</h1>
        <p class="subtitle">
          Don't have an account?
          <button type="button" class="link-inline" @click="goRegister">
            Sign up
          </button>
        </p>
      </header>

      <div class="field">
        <label class="label" for="login-email">Your email address</label>
        <input
          id="login-email"
          v-model="email"
          class="input"
          type="email"
          autocomplete="email"
          placeholder=""
        />
      </div>

      <div class="field">
        <label class="label" for="login-password">Your password</label>
        <div class="password-wrap">
          <input
            id="login-password"
            v-model="password"
            class="input input-password"
            :type="showPassword ? 'text' : 'password'"
            autocomplete="current-password"
            placeholder=""
          />
          <button
            type="button"
            class="eye-btn"
            :aria-label="showPassword ? 'Hide password' : 'Show password'"
            @click="showPassword = !showPassword"
          >
            <span class="material-icons eye-icon">{{
              showPassword ? 'visibility' : 'visibility_off'
            }}</span>
          </button>
        </div>
      </div>

      <button type="button" class="link-forgot" @click="handleForgotPassword">
        I've forgotten my password
      </button>

      <button
        type="button"
        class="btn-primary"
        :class="{ 'btn-primary--disabled': isLoading }"
        :disabled="isLoading"
        @click="handleLogin"
      >
        <span v-if="isLoading" class="btn-spinner" />
        <span v-else>Log in</span>
      </button>
    </div>

    <footer class="footer">{{ versionLabel }}</footer>
  </div>
</template>

<script>
import { mapActions } from 'vuex';
import pkg from '../../package.json';

export default {
  name: 'LoginView',
  data() {
    return {
      email: '',
      password: '',
      isLoading: false,
      showPassword: false,
      bgSrc: require('../assets/login-bg-top-right.png'),
      versionLabel: `${pkg.version} (v217)`,
    };
  },
  methods: {
    ...mapActions('auth', ['login']),
    handleForgotPassword() {
      window.alert(
        'Please contact your administrator to reset your password.'
      );
    },
    async handleLogin() {
      if (!this.email.trim()) {
        window.alert('Please enter your email');
        return;
      }
      if (!this.password) {
        window.alert('Please enter your password');
        return;
      }

      this.isLoading = true;
      try {
        await this.login({
          email: this.email.trim().toLowerCase(),
          password: this.password,
        });
        this.$router.replace({ name: 'DriverHome' });
      } catch (error) {
        window.alert(
          error.message || 'Invalid credentials. Please try again.'
        );
      } finally {
        this.isLoading = false;
      }
    },
    goRegister() {
      this.$router.push({ name: 'Register' });
    },
  },
};
</script>

